// The models folded from their real crease patterns, solved offline into keyframes: the traditional crane and flapping bird, both
// public-domain designs, their crease patterns from Origami Simulator by Amanda Ghassaei (github.com/amandaghassaei/OrigamiSimulator,
// MIT License, Copyright (c) 2018 Amanda Ghassaei). Each pattern was folded with a bar-and-hinge solver (every crease driven toward
// its fold together, as Origami Simulator does), stopped a little short of flat so stacked layers stay apart, and turned toward the
// angle it is best seen from as it folds. See ./origami.ts Baked.
//
// The traditional lily (origami.me/lily) has no published crease pattern, so it is folded here from its diagram: the frog base from
// Origami Simulator's frogBase.svg, solved as above, then each face's flap folded down and its edges laid on the centre line, every
// fold an exact turn about its crease, then the four petals opened out and curled as the diagram's last step does.
//
// The orchid is Robert J. Lang's Orchid Blossom (Opus 392, 2002, langorigami.com/artwork/orchid; instructions in his Origami
// Design Secrets), from his crease pattern as Origami Simulator ships it (langOrchid.svg). It is folded flat to its base as above,
// then shaped the way the folded model is: the creases round the centre let go and the six long flaps drawn out evenly round it.
import type { Baked } from './origami'

/** Keys written as whole thousandths, each value the change from the key before, which keeps a big model small. */
function deltas(n: number, d: number[]): number[][] {
  const at = new Array<number>(n).fill(0)
  const keys: number[][] = []
  for (let i = 0; i < d.length; i += n) keys.push(at.map((v, j) => (at[j] = v + d[i + j]) / 1000))
  return keys
}

